Per_Exec_Wake can_per_execute( void )
{
    #define CAN_PER_OBJ (((Can_Per_Node*)curr)->can_per_obj)
    
    Per_Exec_Wake wake_state = PER_EXEC_SLEEP;

	Fifo_Node *curr , *temp ;
	
	for( curr = can_per_fifo_exec->rhs ; curr != can_per_fifo_exec ; curr = curr->rhs )
	{
		if( (CAN_PER_OBJ.req_done) || out_exec( NULL , (Out)(&CAN_PER_OBJ))      )
		{
			CAN_PER_OBJ.req_done = FALSE ; 
													
			temp = curr->rhs ; 
			
			fifo_unlink( curr ) ; 

			fifo_insert( can_per_fifo_free , curr ) ; 
			
			curr = temp->lhs ; 
		}
		else
		{
			wake_state = PER_EXEC_WAKE ;
		}
	}	
	
	return wake_state ; 

    #undef CAN_PER_OBJ
}
        
